# Union fjerner dobbelttelling der håndtegnede sjøbelter berører/overlapper ved pirrøtter.
from shapely.geometry import Polygon
from shapely.ops import unary_union
for cid,d in D.items():
 if d['action']!='include' or len({p['frame'] for p in d['parts']})!=1:continue
 ps=[Polygon(p['pixels']) for p in d['parts']]
 assert all(g.is_valid for g in ps),cid
 u=unary_union(ps)
 if sum(g.area for g in ps)-u.area>.001:
  frame=d['parts'][0]['frame'];d['normalization']='Union av overlappende manuelt tegnede deler ved pirrøtter; ingen automatisk havnebuffer.'
  d['parts']=[dict(frame=frame,pixels=list(g.exterior.coords)[:-1]) for g in getattr(u,'geoms',[u])]
